<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$nonce=\ClyoNutri\Core\Http\SecurityHeaders::nonce(); ?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lista de espera — Clyo Nutri</title>
<style>body{font:16px system-ui;margin:0;background:var(--neutral-gray-50, #F9FAFB);color:var(--botanical-forest-900, #0F3E17)}main{max-width:720px;margin:auto;padding:24px}section,article{background:white;padding:20px;border:1px solid var(--botanical-sage-200, #D3E5D5);border-radius:12px;margin:16px 0}label{display:block;margin:14px 0}input,select,button{font:inherit;padding:9px;max-width:100%;box-sizing:border-box}button{background:var(--semantic-success-text, #0A5F63);color:white;border:0;border-radius:6px;cursor:pointer}button:disabled{opacity:.5}a{color:var(--semantic-success-text, #0A5F63)}#status{min-height:1.5em}.dates{display:flex;gap:16px;flex-wrap:wrap}</style><link rel="stylesheet" href="/assets/css/operational-ui.css?v=v54-63">
</head><body><main>
<h1>Lista de espera</h1><p><?= $e($selectedProf['name']) ?> — <?= $e($selectedProf['clinic_name']) ?></p>
<p>Você receberá uma oferta quando houver uma vaga compatível. A vaga ficará reservada por um prazo e só será agendada depois do seu aceite. Entre no <a href="/paciente/app" target="_blank" rel="noopener">Portal do Paciente</a> e volte a esta página.</p>
<p id="status" class="op-message op-message--info" role="status" aria-live="polite"></p>
<section><h2>Entrar na lista</h2><?php if(!$waitlistCanJoin): ?><p>Novas inscrições estão indisponíveis neste link. Você pode acompanhar e cancelar seus pedidos abaixo.</p><?php endif; ?><form id="join" <?= !$waitlistCanJoin?'hidden':'' ?>>
<div class="dates"><label>De <input type="date" name="date_from" required></label><label>Até <input type="date" name="date_to" required></label></div>
<p>Escolha um intervalo futuro de até 31 dias.</p>
<div class="dates"><label>A partir de <input type="time" name="time_from" value="08:00" required></label><label>Terminar até <input type="time" name="time_to" value="18:00" required></label></div>
<label>Modalidade <select name="modality"><option value="presential">Presencial</option><option value="telehealth">Teleconsulta</option></select></label>
<label>Serviço <select name="service_type"><option value="first_visit">Primeira consulta</option><option value="follow_up">Retorno</option></select></label>
<button type="submit">Entrar na lista de espera</button></form></section>
<section><h2>Meus pedidos e ofertas</h2><button id="refresh" type="button">Atualizar</button><div id="items"></div></section>
<p><a href="/agendar/<?= !empty($selectedProf['slug'])?$e(rawurlencode((string)$selectedProf['slug'])):(int)$profId ?>">Voltar aos horários disponíveis</a></p>
<script nonce="<?= $e($nonce) ?>">(function(){
'use strict';
var prof=<?= (int)$profId ?>,term=<?= (int)($consentTerm['id']??0) ?>,tz=<?= json_encode(\ClyoNutri\Domain\Booking\BookingCalendarService::tz()->getName(), JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>,termVersion=<?= json_encode((string)($consentTerm['version']??''), JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;
var status=document.getElementById('status'),items=document.getElementById('items');
function request(path,body){return fetch(path,{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-ClyoNutri-Web':'1'},body:body?JSON.stringify(body):undefined}).then(function(r){return r.json().then(function(d){if(!r.ok)throw new Error(r.status===401?'Entre no Portal do Paciente para continuar.':(d.error||'Não foi possível concluir a ação.'));return d;});});}
function message(text){status.textContent=text;}
function refresh(){request('/api/v1/patient/waitlist').then(function(d){items.replaceChildren();if(!d.items.length)items.textContent='Você não tem pedidos ativos.';d.items.forEach(function(w){var card=document.createElement('article'),text=document.createElement('p');text.textContent=(w.professional_name||'Profissional')+' · '+w.date_from+' a '+w.date_to+' · '+w.time_from+'–'+w.time_to+' · '+({waiting:'Aguardando vaga',offered:'Oferta disponível',expired:'Oferta expirada'}[w.status]||w.status);card.append(text);
if(w.status==='offered'&&w.hold_token){var detail=document.createElement('p');detail.textContent='Horário: '+w.scheduled_at+' ('+tz+'). Prazo para aceitar: '+new Date(w.expires_at_utc.replace(' ','T')+'Z').toLocaleString('pt-BR');card.append(detail);var label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';label.append(check,document.createTextNode(' Li e aceito o termo de assistência clínica vigente (versão '+termVersion+'), disponível no Portal do Paciente.'));card.append(label);var accept=document.createElement('button');accept.type='button';accept.textContent='Aceitar e agendar';accept.disabled=true;check.addEventListener('change',function(){accept.disabled=!check.checked;});accept.addEventListener('click',function(){accept.disabled=true;request('/api/v1/patient/booking/confirm',{hold_token:w.hold_token,terms_accepted:true,consent_term_id:term}).then(function(){message('Agendamento registrado. Acompanhe pelo Portal do Paciente.');refresh();}).catch(function(e){message(e.message);accept.disabled=!check.checked;});});card.append(accept);}
var cancel=document.createElement('button');cancel.type='button';cancel.textContent='Sair da lista';cancel.style.marginLeft='12px';cancel.addEventListener('click',function(){cancel.disabled=true;request('/api/v1/patient/waitlist/'+w.id+'/cancel',{}).then(function(){message('Solicitação cancelada.');refresh();}).catch(function(e){message(e.message);cancel.disabled=false;});});card.append(cancel);items.append(card);});}).catch(function(e){message(e.message);});}
document.getElementById('join').addEventListener('submit',function(ev){ev.preventDefault();var body=Object.fromEntries(new FormData(ev.target));body.professional_id=prof;var button=ev.target.querySelector('button');button.disabled=true;request('/api/v1/patient/waitlist',body).then(function(){message('Você entrou na lista. Aguarde uma oferta; nenhuma consulta foi confirmada.');refresh();}).catch(function(e){message(e.message);}).finally(function(){button.disabled=false;});});
document.getElementById('refresh').addEventListener('click',refresh);window.addEventListener('focus',refresh);refresh();
})();</script></main></body></html>
